from PIL import Image

def is_valid_image(path):
    """Check if an image file is valid and can be opened."""
    try:
        with Image.open(path) as img:
            img.verify()  # Verify it's a valid image
            img.load()    # Try to load it
        return True
    except Exception:
        return False

def remove_corrupted_images(directory):
    """Remove corrupted images from the directory."""
    removed = []
    if os.path.isfile(directory):  # If it's a file, just check it
        if not is_valid_image(directory):
            os.remove(directory)
            removed.append(directory)
        return removed

    if not os.path.isdir(directory):
        return removed

    for root, dirs, files in os.walk(directory):
        for file in files:
            filepath = os.path.join(root, file)
            if not is_valid_image(filepath):
                try:
                    os.remove(filepath)
                    removed.append(filepath)
                    print(f"Removed corrupted file: {filepath}")
                except Exception as e:
                    print(f"Could not remove {filepath}: {e}")
    return removed
